<!doctype html>
<html lang="ko">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}">
<title>회사 이메일 AI 분석함 | {{ \App\Support\Org::name() }}</title>
<style>
:root{--b:#087be6;--nav:#0f2744;--line:#dce5ef;--muted:#6c7b90;--bg:#f4f7fb;--green:#07865c;--amber:#c66b00;--red:#dc2626}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#10223d;font:14px/1.45 Inter,"Noto Sans KR",system-ui,sans-serif}button,input,select{font:inherit}.shell{min-height:100vh}.top{height:58px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 24px}.crumb{color:var(--muted);font-size:12px}.crumb b{color:#172b47}.content{padding:22px;max-width:1700px;margin:auto}.hero{margin-bottom:15px}.hero h1{font-size:28px;margin:0 0 4px}.hero p{margin:0;color:var(--muted)}.connection,.card,.pane{background:#fff;border:1px solid var(--line);border-radius:13px}.connection{padding:13px 17px;display:flex;align-items:center;gap:12px;margin-bottom:14px}.outlook{width:38px;height:38px;border-radius:9px;background:#087be6;color:#fff;display:grid;place-items:center;font-weight:900}.grow{flex:1}.mail{font-weight:800;font-size:15px}.sub{font-size:11px;color:var(--muted);margin-top:2px}.pill{display:inline-flex;padding:4px 8px;border-radius:999px;font-size:10px;font-weight:800}.ok{background:#e8f8f1;color:var(--green)}.warn{background:#fff4df;color:var(--amber)}.bad{background:#fff0f0;color:var(--red)}.btn{border:1px solid var(--line);border-radius:8px;background:#fff;color:#16304e;padding:8px 11px;font-weight:750;cursor:pointer}.btn:hover{border-color:#87a9cf}.btn.primary{background:var(--b);border-color:var(--b);color:#fff}.btn.danger{color:var(--red)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:14px}.card{padding:13px 16px}.card small{color:var(--muted);font-weight:700}.card strong{display:block;font-size:25px;margin-top:2px}.workspace{display:grid;grid-template-columns:350px minmax(390px,1fr) 420px;gap:12px;min-height:590px}.pane{overflow:hidden;min-width:0}.pane-head{padding:13px 15px;border-bottom:1px solid var(--line);font-weight:850}.search{margin:11px 12px;width:calc(100% - 24px);border:1px solid var(--line);border-radius:8px;padding:9px}.threads{max-height:535px;overflow:auto}.thread{display:block;width:100%;text-align:left;border:0;border-bottom:1px solid #edf1f6;background:#fff;padding:13px 14px;cursor:pointer}.thread:hover,.thread.active{background:#edf7ff}.thread.active{box-shadow:inset 3px 0 var(--b)}.thread-title{font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.thread-meta{display:flex;justify-content:space-between;color:var(--muted);font-size:11px;margin-top:5px}.tag{display:inline-block;border-radius:999px;background:#e9f2ff;color:#2764a8;padding:3px 7px;font-size:10px;font-weight:800;margin:6px 4px 0 0}.tag.amber{background:#fff1d8;color:#a75a00}.body{padding:16px}.empty{display:grid;place-items:center;min-height:470px;color:var(--muted);text-align:center}.subject{font-size:17px;font-weight:850;margin-bottom:10px}.message{border-left:3px solid #a9bfd8;padding:9px 11px;margin:9px 0;background:#f8fafc;border-radius:0 8px 8px 0}.message.outgoing{border-left-color:var(--b)}.message-head{display:flex;justify-content:space-between;gap:8px;font-size:11px;color:var(--muted)}.message p{white-space:pre-wrap;margin:7px 0 0;color:#344761}.docs{border-top:1px solid var(--line);margin-top:14px;padding-top:12px}.doc{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:9px;border:1px solid var(--line);border-radius:8px;margin-top:7px}.doc a{color:var(--b);font-weight:750;text-decoration:none}.analysis{padding:14px}.box{border:1px solid var(--line);border-radius:10px;padding:12px;margin-bottom:10px}.box h3{font-size:12px;margin:0 0 7px}.box p{margin:0;color:#40536c;white-space:pre-wrap}.rows div{display:flex;justify-content:space-between;gap:12px;padding:7px 0;border-bottom:1px solid #edf1f6}.rows div:last-child{border:0}.rows span{color:var(--muted)}.share{background:#fff8e9;border-color:#f5d392}.share select{width:100%;border:1px solid var(--line);border-radius:7px;padding:8px;margin:7px 0}.ask input{width:100%;border:1px solid var(--line);border-radius:8px;padding:9px;margin:6px 0}.answer{margin-top:8px;padding:10px;background:#eff7ff;border-radius:8px;white-space:pre-wrap}.hidden{display:none}.toast{position:fixed;right:20px;bottom:20px;background:#13233b;color:#fff;padding:11px 15px;border-radius:9px;display:none;z-index:20}.toast.show{display:block}@media(max-width:1100px){.workspace{grid-template-columns:300px 1fr}.analysis-pane{grid-column:1/-1}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.content{padding:12px}.workspace{display:block}.pane{margin-bottom:10px}.stats{grid-template-columns:repeat(2,1fr)}.connection{align-items:flex-start;flex-wrap:wrap}}
</style>
</head>
<body><div class="shell">
@unless(request()->boolean('embed'))<div class="top"><div class="crumb">{{ \App\Support\Org::name() }} 통합관리　›　문서함　›　<b>회사 이메일 분석함</b></div><a class="btn" href="/">ERP 홈</a></div>@endunless
<main class="content">
<div class="hero"><h1>회사 이메일 AI 분석함</h1><p>Outlook 이메일과 첨부파일을 자동 분석하고, 공유를 승인한 업무만 프로젝트 문서함에 정리합니다.</p></div>
@forelse($connections as $connection)
<section class="connection"><div class="outlook">O</div><div class="grow"><div class="mail">{{ $connection->email }}</div><div class="sub">최근 동기화 {{ $connection->last_synced_at?->diffForHumans() ?: '대기 중' }} · 개인 원문은 본인만 열람</div></div><span class="pill {{ $connection->status === 'active' ? 'ok' : ($connection->status === 'error' ? 'bad' : 'warn') }}">{{ ['active'=>'정상 연결','error'=>'확인 필요','disconnected'=>'연결 해제'][$connection->status] ?? $connection->status }}</span>@if($connection->status !== 'disconnected')<button class="btn sync" data-id="{{ $connection->id }}">↻ 지금 동기화</button><button class="btn danger disconnect" data-id="{{ $connection->id }}">연결 해제</button>@else<a class="btn primary" href="{{ route('email-ai.microsoft.connect') }}" target="_top">Outlook 다시 연결</a>@endif</section>
@empty
<section class="connection"><div class="outlook">O</div><div class="grow"><div class="mail">Outlook이 아직 연결되지 않았습니다</div><div class="sub">비밀번호는 ERP에 저장하지 않습니다. Microsoft 로그인 화면에서 본인이 직접 승인합니다.</div></div>@if($configured)<a class="btn primary" href="{{ route('email-ai.microsoft.connect') }}" target="_top">Outlook 연결</a>@else<span class="pill warn">관리자 환경설정 필요</span>@endif</section>
@endforelse
<div class="stats"><div class="card"><small>오늘 새 이메일</small><strong>{{ $stats['new'] }}</strong></div><div class="card"><small>분류 확인 필요</small><strong>{{ $stats['review'] }}</strong></div><div class="card"><small>회신 필요</small><strong>{{ $stats['response'] }}</strong></div><div class="card"><small>분석 실패</small><strong>{{ $stats['failed'] }}</strong></div></div>
<div class="workspace">
 <section class="pane"><div class="pane-head">이메일 대화</div><input class="search" id="filter" placeholder="제목·발신자 검색"><div class="threads" id="threads">
 @forelse($threads as $thread)<button class="thread" data-id="{{ $thread->id }}" data-search="{{ mb_strtolower($thread->subject.' '.implode(' ',(array)$thread->participants)) }}"><div class="thread-title">{{ $thread->subject ?: '(제목 없음)' }}</div><div class="thread-meta"><span>{{ collect($thread->participants)->first() }}</span><span>{{ $thread->last_message_at?->format('m-d H:i') }}</span></div>@if($thread->project)<span class="tag">{{ $thread->project->project_code }}</span>@endif<span class="tag {{ $thread->visibility === 'private' ? '' : 'amber' }}">{{ $thread->visibility === 'private' ? '본인 전용' : '프로젝트 공유' }}</span>@if($thread->needs_response)<span class="tag amber">회신 필요</span>@endif</button>@empty<div class="empty">연결 후 이메일이 이곳에 정리됩니다.<br>화면을 닫아도 서버가 계속 분석합니다.</div>@endforelse
 </div></section>
 <section class="pane"><div class="pane-head">원문 및 첨부</div><div class="body" id="message-pane"><div class="empty">왼쪽에서 이메일 대화를 선택하세요.</div></div></section>
 <section class="pane analysis-pane"><div class="pane-head">AI 분석 결과</div><div class="analysis" id="analysis-pane"><div class="box"><h3>한글 요약</h3><p id="summary">이메일을 선택하면 요약과 업무 정보를 보여줍니다.</p></div><div class="box rows"><div><span>연결 프로젝트</span><b id="project-label">-</b></div><div><span>문서 유형</span><b id="classification">-</b></div><div><span>회신 필요</span><b id="needs-response">-</b></div><div><span>회신 기한</span><b id="response-due">-</b></div><div><span>신뢰도</span><b id="confidence">-</b></div></div><div class="box share hidden" id="share-box"><h3>회사 업무로 공유</h3><p>공유 전에는 나만 볼 수 있습니다. 프로젝트를 선택하고 승인하면 담당자와 AI 질문에서 사용할 수 있습니다.</p><select id="share-project"><option value="">프로젝트 선택</option>@foreach($projects as $project)<option value="{{ $project->id }}">{{ $project->project_code }} · {{ $project->name }}</option>@endforeach</select><button class="btn primary" id="share-button">프로젝트 문서함에 공유</button> <button class="btn" id="private-button">본인 전용으로 변경</button></div><div class="box ask"><h3>AI에게 질문</h3><input id="question" placeholder="예: 방문은 언제 입고된다고 했어?"><button class="btn primary" id="ask-button">질문하기</button><div class="answer hidden" id="answer"></div></div></div></section>
</div></main><div class="toast" id="toast"></div></div>
<script>
const csrf=document.querySelector('meta[name=csrf-token]').content;let selected=null;
const toast=(m)=>{let e=document.getElementById('toast');e.textContent=m;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),3200)};
async function request(url,opt={}){opt.headers=Object.assign({'Accept':'application/json','X-CSRF-TOKEN':csrf,'Content-Type':'application/json'},opt.headers||{});let r=await fetch(url,opt),j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||j.message||'처리하지 못했습니다.');return j}
document.querySelectorAll('.sync').forEach(b=>b.onclick=async()=>{try{toast((await request('/email-ai/connections/'+b.dataset.id+'/sync',{method:'POST'})).message)}catch(e){toast(e.message)}});
document.querySelectorAll('.disconnect').forEach(b=>b.onclick=async()=>{if(!confirm('이메일 연결을 해제할까요? 이미 편철한 문서는 남습니다.'))return;try{toast((await request('/email-ai/connections/'+b.dataset.id,{method:'DELETE'})).message);setTimeout(()=>location.reload(),700)}catch(e){toast(e.message)}});
document.getElementById('filter').oninput=function(){let q=this.value.toLowerCase();document.querySelectorAll('.thread').forEach(e=>e.style.display=e.dataset.search.includes(q)?'block':'none')};
document.querySelectorAll('.thread').forEach(b=>b.onclick=()=>openThread(b));
async function openThread(button){document.querySelectorAll('.thread').forEach(x=>x.classList.remove('active'));button.classList.add('active');selected=button.dataset.id;let j;try{j=await request('/email-ai/threads/'+selected)}catch(e){toast(e.message);return}let t=j.thread;document.getElementById('message-pane').innerHTML='<div class="subject">'+esc(t.subject||'(제목 없음)')+'</div>'+t.messages.map(m=>'<div class="message '+m.direction+'"><div class="message-head"><b>'+esc(m.sender||'-')+'</b><span>'+esc((m.sentAt||'').replace('T',' ').slice(0,16))+'</span></div><p>'+esc(m.preview||'(본문 미리보기 없음)')+'</p>'+(m.previewUrl?'<a class="btn" target="_blank" href="'+m.previewUrl+'">원문 열기</a>':'')+'</div>').join('')+'<div class="docs"><b>첨부·분석 문서</b>'+t.documents.map(d=>'<div class="doc"><div><b>'+esc(d.title)+'</b><div class="sub">'+esc(d.type||'분석 중')+' · '+esc(d.status)+'</div></div><a target="_blank" href="'+d.previewUrl+'">열기</a></div>').join('')+'</div>';document.getElementById('summary').textContent=t.summary||'AI 분석 중입니다.';document.getElementById('project-label').textContent=t.projectId||'-';document.getElementById('classification').textContent=t.classification||'-';document.getElementById('needs-response').textContent=t.needsResponse?'예':'아니오';document.getElementById('response-due').textContent=t.responseDue||'-';document.getElementById('confidence').textContent=t.confidence?t.confidence+'%':'-';document.getElementById('share-box').classList.toggle('hidden',!t.owner);document.getElementById('share-project').value=t.projectId||''}
document.getElementById('share-button').onclick=()=>share('project');document.getElementById('private-button').onclick=()=>share('private');async function share(v){if(!selected)return toast('이메일을 먼저 선택하세요.');try{let j=await request('/email-ai/threads/'+selected+'/share',{method:'PATCH',body:JSON.stringify({visibility:v,project_id:v==='project'?document.getElementById('share-project').value:null})});toast(j.message);setTimeout(()=>location.reload(),700)}catch(e){toast(e.message)}}
document.getElementById('ask-button').onclick=async()=>{let q=document.getElementById('question').value.trim();if(!q)return toast('질문을 입력하세요.');let box=document.getElementById('answer');box.textContent='자료를 확인하고 있습니다…';box.classList.remove('hidden');try{let j=await request('/email-ai/ask',{method:'POST',body:JSON.stringify({question:q})});box.textContent=j.answer||j.error||'답을 만들지 못했습니다.'}catch(e){box.textContent=e.message}};
function esc(v){let d=document.createElement('div');d.textContent=v==null?'':String(v);return d.innerHTML}let first=document.querySelector('.thread');if(first)openThread(first);
</script></body></html>
